  t("<b>Estado da India = State enterprise</b>", "Directly controlled by the <b>Portuguese Crown</b>; the government was the trader (board: <b>like a PSU / Govt</b>)", "English EIC + Dutch VOC = private companies; <b>French EIC</b> = initially private, later taken over by the French Govt", w=20),
  tb(["Term", "Meaning (board)"], ["<b>Factory</b>", "Not manufacturing: trading post = warehouses + offices + homes of employees + <b>MAY be a fort</b>; from <b>factor</b> = merchant agent; function = <i>Office</i>"], ["<b>Depot</b>", "Warehouse only (bus depot: goods waiting for the ship); no <b>LEJ</b> jurisdiction"], ["<b>Settlement</b>", "Colonial enclave: multiple factories + warehouses, small territorial colony with civil + town administration; collects and consumes LR; <b>sovereign territorial rights L-E-J</b>; taxes only by Ruler / Govt"], ["<b>Farman</b>", "Imperial decree by the Mughal Emperor"], ["<b>Parwana</b>", "Provincial decree by a Governor"], ["<b>Nishan</b>", "Princely decree by a Prince of the Royal Blood"]),
