  two([t("<b>Americas to Old World</b>", "potatoes, maize, sweet potatoes", "pumpkins + squash, cassava, tomatoes", "pineapples, avocados, beans, peanuts", "cashews, cacao, vanilla, chili peppers", "sunflowers, tobacco, quinine, turkeys")], [t("<b>Old World to Americas</b>", "pigs, horses, cattle, chickens, sheep, rats, honeybees", "wheat, rice, barley, oats, rye, bananas, sugarcane", "olives, citrus, coffee, peaches, pears, apples", "carrots, grapes, lettuce, cabbage, onions, soybeans, weeds", "<b>Diseases</b>: bubonic plague, smallpox, typhus, malaria, yellow fever, diphtheria, measles, influenza, whooping cough")]),
  t("<b>Why the Portuguese declined</b>", "<b>i Political</b>: strong regional powers (Persia, Egypt, N India); <b>Marathas</b> (1739 beat Portuguese; Konkan)", "<b>ii Religious backlash</b>: Jesuits + Goa Inquisition", "<b>iii Economic + administrative decay</b>: corruption, indiscipline, employees' piracy + illicit &quot;personal trade&quot;", "<b>iv External competition</b>: English + Dutch (navy, joint-stock finance, discipline)", "<b>v Overextension</b>: focus on <b>Brazil</b> (more lucrative) + no support from Lisbon", w=22),
