  tl(("1600", "<b>Elizabeth I 58-03</b>: 15-yr monopoly (imp)"), ("1601-03", "1st voyage <b>James Lancaster</b> to Indonesia (not India): Java + Sumatra, first EIC factory; looted Portuguese ship <b>Sao Tome</b> in Strait of Malacca (textiles, spices); Dalrymple: first big profit from <b>piracy</b>; dividends; back 1603"), ("1609", "<b>James I 03-25</b>: perpetual monopoly (not imp)"), ("1642-51", "English Civil War: Charles I 25-49 taxed without Parliament; Parliamentarians (Protestant) won; Charles I 25-49 beheaded <b>1649</b>"), ("1651-60", "Republic under <b>Cromwell 51-60</b> (handout writes his years 51-60); died 1658, son briefly, autocratic, unpopular"), ("1657", "<b>Cromwell 51-60</b> declared the old Charter invalid: <b>permanent joint-stock</b>, one continuous capital fund; per-voyage ended (not imp)"), ("1660", "Monarchy restored: <b>Charles II 60-85</b>"), ("1661", "<b>Charles II 60-85</b>: forts, troops, war + peace, civil + criminal jurisdiction = quasi (semi) State (imp, strongest)"), ("1676", "Right to <b>mint</b> (not imp)"), ("1793", "<b>Parliament</b> renews Charters by <b>Acts</b> (imp): first Charter issued by Parliament; democratisation of Britain")),
  bx('pk', "<b>Priority (teacher):</b> learn <b>1600, 1661, 1793</b> first; 1609, 1657, 1676 lower. 1661 = trading company with the legal powers of a State; board: &quot;Charter ACT&quot; = made by Legislature. Also 1688 Glorious Revolution, William III invited by Parliament (Fort William named after him). Why EIC could build an empire: 1661 powers; State powers = territorial + subject jurisdiction; any company follows home law + foreign law; empire = &quot;Company State&quot;."),
  t("<b>Why Indian merchants could not dominate the routes</b>", "(i) <b>Naval power</b>: no armed ocean-going fleets (navy = merchant + military)", "(ii) <b>Capital</b>: VOC 1602 and EIC (1600, by 1657) permanent joint-stock; pool huge sums [gathering rupee from masses]", "(iii) <b>State backing</b>: Mughal State after Akbar 56-05 invested in the territorial army, not a navy; board: modern capitalism absent in India (State = territorial motive)", w=20),
  sec("THE DANES 1616", 'g'),
