  tb(["#", "Link", "How"], ["1", "Disbanded armies = mass unemployment", "<b>Mansabdars lost their military role</b> (teacher corrects 'positions'), sepoys lost livelihood; EIC recruited sepoys from <b>outside</b> the State (<b>Divide and Rule</b>: less keep Bengal sepoys in Bengal Army)"], ["2", "EIC's free army", "EIC commands, can deploy elsewhere (Foreign Policy); <b>EIC armies = State army maintained by subsidy + EIC's own army</b>; every SA = free-of-cost increase"], ["3", "High, rising subsidy", "<b>Drain of Wealth</b>; money could have funded the State's development"], ["4", "Tax hikes", "Rulers unpopular, peasant resentment, <b>peasant revolts</b>"], ["5", "Maladministration charge", "Ruler no power but all responsibility; Resident often breached non-interference; <b>Wajid Ali Shah, Awadh annexed 1856</b>"], ["6", "Territory in lieu of cash", "<b>1801 half of Awadh</b>; <b>1853 Berar from Hyderabad</b>; 'Thanks, Dupleix 42-54' (Northern Sarkars 1751); subsidy = tool of empire building"], ["7", "No alliances possible", "SA = Divide and Rule at subcontinent level; every signatory annexed or permanently dependent"]),
  bx('gr', "<b>Takeaway:</b> EIC got all military + diplomatic power with no responsibility of ruling and no financial burden."),
