  tb(["#", "Why rulers walked in willingly (5)", "Meaning"], ["1", "Protection vs internal revolts", "EIC army inside palace = insurance vs rivals / mutinous nobles"], ["2", "Protection vs external threats", "Feared Maratha Chauth, Mysore, Rohilla more than distant British"], ["3", "Better than annexation", "Subsidy cheaper than annexation / losing war"], ["4", "Royal dignity preserved", "Title, court, ceremony; flag flew"], ["5", "Winning succession disputes", "Board: <b>FACTIONALISM</b>; EIC made military help conditional on signing"]),
  tb(["#", "Year", "State (treaty)", "Circumstances", "GG"], ["1", "<b>1798</b>", "<b>Hyderabad</b> (first)", "Nizam signed for protection vs Marathas + Mysore", "Wellesley 98-05"], ["2", "1799", "<b>Mysore</b> (Wodeyars)", "After 4th Anglo-Mysore War (1798-99); Tipu 82-99 killed at Seringapatam; Wodeyars restored on subsidiary throne", "Wellesley 98-05"], ["3", "1801", "<b>Awadh</b>", "Sadat Ali Khan II defaulted; Henry Wellesley imposed full SA; half annexed", "Wellesley 98-05"], ["4", "June 1802", "<b>Gaikwad of Baroda (Treaty of Cambay)</b>", "EIC help in Gaikwad succession dispute", "Wellesley 98-05"], ["5", "Dec 1802", "<b>Peshwa Bajirao II 96-18 (Treaty of Bassein / Vasai)</b>", "Beaten by Yashwantrao Holkar, fled, signed to regain Peshwaship", "Wellesley 98-05"], ["6", "1803 (or 1804, board)", "<b>Scindia of Gwalior</b>", "Forced, 2nd Anglo-Maratha War (1803-05)", "Wellesley 98-05"], ["7", "1803-05", "<b>Jats, Rajputs, Bundelas</b> (group entry)", "Forced in 2nd A-Ma War; earlier paid Chauth + Sardeshmukhi to Marathas, now subsidy to EIC", "Wellesley 98-05"], ["8", "1805", "<b>Travancore</b>", "EIC help crushing Nair troops' mutiny (unpaid salary); last under Wellesley 98-05 before recall", "Wellesley 98-05"], ["9", "1816", "<b>Bhonsle of Nagpur (Treaty of Nagpur)</b>", "Appa Sahib signed using EIC backing in regency faction fight (resisted over a decade after 2nd A-Ma War)", "Francis Hastings 13-23"], ["10", "1818", "<b>Holkar of Indore (Treaty of Mandsaur)</b>", "Forced after defeat in 3rd Anglo-Maratha War (1817-19)", "Francis Hastings 13-23"]),
  bx('ye', "<b>Count conflict:</b> typed slides/handout say <b>Nine</b> (first seven under Wellesley 98-05); board corrects to <b>TEN</b> and <b>8</b>. Use <b>10 SAs in 20 years (1798-1818); 8 under Wellesley 98-05, 2 under Francis Hastings 13-23.</b> Only if a question counts just named States is it nine. <b>Dates:</b> Scindia 1803 or 1804 (inside 2nd A-Ma War); 4th A-My War '1798-99' in Sec 1 and 6, '1799' in Sec 7 and Ch 7; Seringapatam 'Siege' vs 'Battle' = same event. Handout heading typo 'Nine'."),
  bx('pk', "<b>Board lessons:</b> Hyderabad/Mysore: <i>had India had one common centre (one State over all T) this would not have happened</i>; (IR) <i>enemy/rival should not be ONE</i> (reading: Indian States many, EIC one; check notebook); Mysore: <b>'Don't lose WARS'</b>. First: Hyderabad 1798; last under Wellesley 98-05: Travancore 1805; last of all: Holkar 1818. <b>Empire builders in time order:</b> Clive 57-67, Wellesley 98-05 (18th c); F. Hastings 13-23, Dalhousie 48-56 (19th c; Dalhousie = Ch 14)."),
  tb(["Maratha power post 1761", "Tag", "Proof"], ["Peshwa (Bajirao II 96-18)", "<b>Factionalism</b>", "Beaten by Yashwantrao Holkar (avenging his brother), signed Bassein Dec 1802"], ["Scindia (Gwalior)", "<b>War</b>", "2nd A-Ma War"], ["Holkar (Indore)", "<b>War</b>", "3rd A-Ma War, Mandsaur 1818"], ["Bhonsle (Nagpur)", "<b>Factionalism</b>", "Appa Sahib, regency (N vs N), 1816"], ["Gaikwad (Baroda)", "<b>Factionalism</b>", "Cambay June 1802"]),
  bx('bl', "<b>Factionalism</b> = rival groups fighting over who rules (here regent of Nagpur). Scindia and Bhonsle read Bassein as a Peshwa selling the Confederacy to the British: 2nd A-Ma War followed (Ch 13). <b>Two Treaties of Bassein: 1739</b> (Marathas + Portuguese; Bassein + Salsette) and <b>1802</b> (Peshwa + EIC): know both names Bassein/Vasai."),
  t("<b>Awadh 1798-1801</b>", "<b>1798</b> Sadat Ali Khan II (uncle) offered <b>Rs 76 lakh</b> annual subsidy if <b>John Shore 93-98</b> removed nephew <b>Wazir Ali (1797-98)</b>; Shore obliged", "<b>1801</b> defaulted; Henry Wellesley imposed full SA; <b>half annexed as permanent subsidy</b>: <b>Doab, Gorakhpur, Rohilkhand</b>; revenue = twice the Rs 76 lakh (unfair, handout)", "<b>Ceded Districts</b>; <b>1836 NWP</b> full province; <b>1856</b> rest annexed (Wajid Ali Shah, maladministration); <b>1877 both merged</b>", "Rohilkhand: most annexed by Awadh with EIC help <b>1774</b> (ToA 1765 alliance); small part = <b>Rampur</b> (under Awadh, from 1801 EIC legally)", "Nawab list: Sadat 22-39, Safdar Jung 39-53, Shuja 54-75, Asaf-ud-Dowla 75-97, Wazir Ali 1797-98, uncle Sadat II Ali Khan 1798+", w=26),
  bx('ye', "<b>Not a conflict:</b> 'whole' vs 'half' Awadh: 1801 = half (Ceded Districts), 1856 = remainder. Never write 'Awadh annexed 1801' for the whole State."),
