  tb(["When", "Territory", "Reason / teacher's context"], ["1799", "Mysore territory", "4th A-My War; <b>to Madras Presidency</b>"], ["Early 1801", "Half of Awadh (Ceded Districts)", "Permanent subsidy payment; <b>subsidy as tool of empire building</b>"], ["1801", "<b>Carnatic</b>", "Maladministration, <b>6 years after Md Ali 52-95</b> (1752-1795; loyal ally since 2nd CW) died; context (not on record reason): Nawab had taken <b>many loans from EIC and officers</b> = financial maladministration. Mains: ground maladministration, background heavy debts"], ["1803-05", "2nd A-Ma War: Bhonsle", "Lost significant territory incl. <b>Orissa</b> (taken from Bengal 1751)"], ["1803-05", "2nd A-Ma War: Scindia", "Lost Gujarat territory + <b>all north of Yamuna incl. Delhi</b> ('Now PoIR in Delhi', '[1771-1803]' unclear)"]),
  fl(["GBF 1770", "1772 bankruptcy", "Loan + Regulating Act 1773", "BUT STILL wars", "Pitt's India Act 1784", "BUT STILL wars: 4th A-My 1799, 2nd A-Ma 1803-05", "Recalled: wars costly for winner and loser"], "Why Wellesley 98-05 was recalled", 4),
  bx('gr', "<b>Empire building paid only if wars were short and cheap; his were neither.</b> Wars hurt the economy of both sides (IR note)."),
