  tb(["#", "Reason", "Explanation", "Teacher's ink"], ["1", "<b>No stable alliance</b>", "Expansion + EIC diplomacy", "External ally (France) weak; domestic neighbours rivals"], ["2", "<b>French naval gap</b>", "Dependence on French arms; France busy with American War 1776-83, then Revolutionary Wars 1792-1804; navy no match; no fleet resupplied Mysore", "Underlined"], ["3", "<b>Military Fiscalism over-extension</b>", "War fines (3 crore after 3rd war) drained treasury; EIC relatively rich", "Circled 'BUT': strength became weakness"], ["4", "<b>Seringapatam open to siege</b>", "Three-way coalition surrounded it (1789-92, 1799)", "-"]),
  bx('gr', "<b>Verdict:</b> Cornwallis 86-93 and Wellesley 98-05 judged Mysore too strong and ambitious for Indirect Rule: defeat then subordinate. It fought well and modernised but <b>largely alone</b>."),
