  stl(10, "Because the SA disbanded Mysore's army, the jobless soldiers found a leader."),
  t("<b>Dhondia Wagh</b>", "Ex-prisoner of Tipu 82-99 escaped after 1799; mounted force of <b>demobilised Mysore soldiers</b> (SA disbanded army); raided Mysore-Maratha borderlands <b>1799-1800</b>", "<b>'King of Two Worlds'</b>; threatened EIC supply lines; <b>Colonel Arthur Wellesley</b> sent; <b>killed 1800</b>; EIC formally supreme in south by <b>1801</b>", w=20),
  t("<b>Tipu 82-99's religious policy</b> (syncretic yet contradictory)", t("<b>8.1 Patronage, Mysore heartland</b>", "Sringeri Sharada Math, letters to its Shankaracharya for blessings", "Yajnas before wars; grants to Hindu temples"), t("<b>8.2 Coercion, Malabar + Coorg</b>", "Forced conversions of Nairs + Christians in Malabar; destroyed churches + temples", "<b>1785 Coorg</b> brutalities vs <b>Kodavas</b> (mountain warriors, no licence needed for certain arms; earlier under Hindu Nayakas)"), "Geography N to S: Mysore, Coorg (Western Ghats), Malabar; Coorg linked Seringapatam to coastal ports", "<b>Conclusion:</b> secularism a <b>tactic</b> for domestic stability, not a value (values hardest to change, Psychology)", w=24),
  sec("THE CARNATIC ANNEXED 1801", 'r'),
